using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Networking;
namespace YunJian.Riichi.Editor {
    [InitializeOnLoad] public static class CharacterPackExperiment {
        const string Key="CharacterPackExperiment.Run";
        static CharacterPackExperiment(){EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool(Key,false)){SessionState.SetBool(Key,false);UnityEngine.Object.FindAnyObjectByType<RiichiClient>().gameObject.AddComponent<CharacterPackExperimentCapture>();}};}
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Bootstrap(){if(!SessionState.GetBool(Key,false))return;CharacterPackService.RootOverride=SessionState.GetString(Key+"Root","");CharacterPackService.RespectPreviewAvailability=true;CharacterPackService.ResetForReview();}
        public static void CheckCompatibility(){CharacterPackService.RespectPreviewAvailability=true;CharacterPackService.ResetForReview();if(!CharacterPackService.Supports("yiji",400101)||CharacterPackService.Supports("yiji",400201)||CharacterPackService.Supports("unknown",400101)||!CharacterPackService.ContainsSkin("siqiqiansuili",403305)||!CharacterPackService.ContainsSkin("bamuwei",400709))throw new Exception("Resource compatibility check failed");File.WriteAllText(Path.GetFullPath("../build/character-pack-experiment/compatibility-passed.txt"),"5 resource compatibility assertions passed");Debug.Log("RESOURCE COMPATIBILITY PASS 5");}
        public static void Run(){AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);SessionState.SetString(Key+"Root",Path.GetFullPath("../build/character-pack-experiment/clients/"+Guid.NewGuid().ToString("N")));EditorSceneManager.OpenScene("Assets/Scenes/Table.unity");SessionState.SetBool(Key,true);EditorApplication.isPlaying=true;}
    }
    public sealed class CharacterPackExperimentCapture:MonoBehaviour {
        [Serializable]class Report{public List<string>checks=new List<string>();public string githubSource;public long bundleBytes;public int githubDownloads,lanRangeRequests;public bool androidPhonesTested=false;}
        readonly Report report=new Report();readonly List<string> errors=new List<string>();RiichiClient client;LobbyController lobby;CharacterPackService service;CharacterPackShareServer source,relay;string output;float clock=10;RoomReply rawReply;
        void Log(string text,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception)errors.Add(text);}
        IEnumerator Start(){output=Path.GetFullPath("../build/character-pack-experiment/render");Directory.CreateDirectory(output);if(File.Exists(Path.Combine(output,"failed.txt")))File.Delete(Path.Combine(output,"failed.txt"));Application.logMessageReceived+=Log;var stack=new Stack<IEnumerator>();stack.Push(Capture());while(stack.Count>0){object next=null;try{var top=stack.Peek();if(!top.MoveNext()){stack.Pop();continue;}next=top.Current;if(next is IEnumerator sub){stack.Push(sub);continue;}}catch(Exception ex){File.WriteAllText(Path.Combine(output,"failed.txt"),ex.ToString());Debug.LogException(ex);Cleanup();EditorApplication.Exit(1);yield break;}yield return next;}Check(errors.Count==0,"No Unity runtime errors");File.WriteAllText(Path.Combine(output,"checks.json"),JsonUtility.ToJson(report,true));Cleanup();Debug.Log("CHARACTER PACK EXPERIMENT PASS "+report.checks.Count);EditorApplication.Exit(0);}
        void Check(bool value,string label){if(!value)throw new Exception(label);report.checks.Add(label);Debug.Log("PACK CHECK "+label);}
        IEnumerator Hold(int count=5){clock+=count/30f;lobby.DesignPreviewClock=clock;for(int i=0;i<count;i++)yield return null;}
        IEnumerator Shot(string name){yield return Hold(3);yield return new WaitForEndOfFrame();var image=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(Path.Combine(output,name+".png"),image.EncodeToPNG());Destroy(image);}
        IEnumerator Until(Func<bool> ready,string label,float seconds=40){float deadline=Time.realtimeSinceStartup+seconds;while(!ready()){if(Time.realtimeSinceStartup>deadline)throw new Exception("Timeout: "+label);yield return null;}}
        IEnumerator Ui(string id){CharacterResourceUi.Current.ReviewPress=id;yield return Hold(6);}
        IEnumerator Raw(RequestBody body){using(var web=new UnityWebRequest("http://127.0.0.1:8765/api","POST")){web.uploadHandler=new UploadHandlerRaw(System.Text.Encoding.UTF8.GetBytes(JsonUtility.ToJson(body)));web.downloadHandler=new DownloadHandlerBuffer();web.SetRequestHeader("Content-Type","application/json");yield return web.SendWebRequest();if(web.result!=UnityWebRequest.Result.Success)throw new Exception(web.error);rawReply=JsonUtility.FromJson<RoomReply>(web.downloadHandler.text);Check(rawReply.ok,"Room API "+body.op);}}
        string HostToken=>(string)typeof(RiichiClient).GetField("token",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(client);
        IEnumerator WaitDownload(){yield return Until(()=>!service.Busy,"resource download",360);Check(string.IsNullOrEmpty(service.Error),service.Error.Length>0?service.Error:"Download completed without error");}
        IEnumerator Capture(){
            client=GetComponent<RiichiClient>();client.BeginLobbyValidation("character-pack-review");lobby=client.Lobby;service=CharacterPackService.Instance;CharacterRoster.BeginPreview();CharacterRoster.Dorm=CharacterRoster.Find("yiji");CharacterRoster.Reorder(new[]{"bamuwei","yiji","erjietang","weilai","siqiqiansuili"});AudioListener.pause=true;Application.targetFrameRate=30;
            var view=EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));view.GetType().GetMethod("SetCustomResolution",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(view,new object[]{new Vector2(1750,800),"Character pack experiment"});yield return Hold(10);lobby.DesignPreviewGardenEntry();yield return Hold(45);
            Check(CharacterPackService.Installed("yiji")&&CharacterPackService.Installed("erjietang"),"Both protected base characters are present");Check(!CharacterPackService.Delete("yiji",out _)&&!CharacterPackService.Delete("erjietang",out _),"Both base characters reject deletion");Check(!CharacterPackService.Installed("bamuwei"),"八木唯 starts uninstalled");
            CharacterResourceUi.Current.OfferStartup();yield return Shot("startup-choice");yield return Ui("startup-skip");client.LobbyOpenSettings();var settings=(NativeSettingsUi)typeof(RiichiClient).GetField("nativeSettings",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(client);settings.Tab=2;yield return Shot("settings-before");client.LobbyCloseSettings();
            lobby.PreviewDorm("yiji");yield return Shot("dorm-locked");lobby.ValidationPress("dorm-character-bamuwei");yield return Shot("download-confirm");var pack=CharacterPackService.Find("bamuwei");report.githubSource=pack.url;report.bundleBytes=pack.bytes;yield return Ui("resource-prompt-download");yield return Until(()=>service.Busy,"GitHub download start");yield return Until(()=>service.Progress>.05f||!service.Busy,"GitHub bytes received",150);yield return Shot("github-progress");yield return WaitDownload();report.githubDownloads++;Check(CharacterPackService.HashFile(CharacterPackService.FilePath(pack))==pack.sha256,"Actual GitHub download matches trusted SHA256");Check(CharacterRoster.Texture("Skins/400701/full")!=null&&CharacterVoices.Clip("bamuwei","riichi")!=null,"Downloaded illustration and voice load from bundle");
            CharacterResourceUi.Current.Close();lobby.PreviewDorm("bamuwei",400701);yield return Shot("dorm-installed");lobby.PreviewDorm("bamuwei",400706);yield return Hold(20);yield return Shot("dynamic-400706");lobby.PreviewDorm("bamuwei",400709);yield return Hold(20);yield return Shot("dynamic-400709");
            lobby.PreviewHideCharacters();lobby.PreviewRole("bamuwei");yield return Hold(5);Check(lobby.ValidationTarget("battle-character-bamuwei").width>0&&lobby.ValidationTarget("battle-character-weilai").width==0,"Battle roster exposes only installed characters");yield return Shot("battle-installed");lobby.PreviewHideCharacters();
            string sourceFile=Path.Combine(output,"verified-source.bundle");File.Copy(CharacterPackService.FilePath(pack),sourceFile,true);source=new CharacterPackShareServer{Enabled=true,ReviewChunkDelayMs=3};source.SetEntries(new[]{new CharacterPackShareServer.Entry{key=pack.key,hash=pack.sha256,bytes=pack.bytes,path=sourceFile}});string sourceUrl="http://127.0.0.1:"+source.Port+"/packs/"+pack.sha256+"?ticket="+source.Ticket;relay=new CharacterPackShareServer{Enabled=true};relay.SetEntries(new[]{new CharacterPackShareServer.Entry{key=pack.key,hash=pack.sha256,bytes=pack.bytes,url=sourceUrl}});string relayUrl="http://127.0.0.1:"+relay.Port+"/packs/"+pack.sha256+"?ticket="+relay.Ticket;
            CharacterRoster.Use("bamuwei",400706);CharacterRoster.Star("bamuwei");CharacterRoster.TogglePool("bamuwei",400706);CharacterPackService.Pin("bamuwei");Check(!CharacterPackService.Delete("bamuwei",out _),"Active resource pin rejects deletion");CharacterPackService.Unpin("bamuwei");Check(CharacterPackService.Delete("bamuwei",out _),"Optional bundle can be deleted");Check(!File.Exists(CharacterPackService.FilePath(pack))&&CharacterRoster.Active.character=="yiji"&&!CharacterRoster.Favorite("bamuwei")&&!CharacterRoster.Pool.Any(p=>p.character=="bamuwei"),"Deletion frees bundle and clears selection, star and random candidates");lobby.PreviewDorm("yiji");yield return Shot("dorm-after-delete");
            service.Download("bamuwei",relayUrl);yield return Until(()=>service.Progress>.15f&&service.Busy,"partial LAN transfer");service.Cancel();yield return Until(()=>!service.Busy,"transfer cancellation");string partial=CharacterPackService.FilePath(pack)+".part";Check(File.Exists(partial)&&new FileInfo(partial).Length>0&&!CharacterPackService.Installed("bamuwei"),"Cancellation preserves partial bytes without enabling the role");service.Download("bamuwei",relayUrl);yield return Shot("lan-resume-progress");yield return WaitDownload();Check(source.RangeRequests>0&&relay.RangeRequests>0,"LAN host relay forwards HTTP range and resumes a partial pack");report.lanRangeRequests=relay.RangeRequests;Check(CharacterPackService.Installed("bamuwei"),"LAN installation enables the same roster state");
            yield return Until(()=>!CharacterPackService.Pinned("bamuwei"),"source release");Check(CharacterPackService.Delete("bamuwei",out _),"Optional role can be removed again");byte original;using(var file=new FileStream(sourceFile,FileMode.Open,FileAccess.ReadWrite)){file.Position=256;original=(byte)file.ReadByte();file.Position=256;file.WriteByte((byte)(original^255));}service.Download("bamuwei",relayUrl);yield return Until(()=>!service.Busy,"corrupt transfer");Check(!CharacterPackService.Installed("bamuwei")&&service.Error.Contains("校验失败"),"Corrupted LAN content is rejected before installation");using(var file=new FileStream(sourceFile,FileMode.Open,FileAccess.Write)){file.Position=256;file.WriteByte(original);}service.Download("bamuwei",relayUrl);yield return WaitDownload();
            client.LobbyOpenSettings();settings.Tab=2;yield return Shot("settings-installed");client.LobbyCloseSettings();CharacterResourceUi.Current.Close();
            yield return RoomCase(false);yield return RoomCase(true);
            source.SetEntries(CharacterPackService.All.Where(p=>p.available&&!p.builtin).Select(p=>new CharacterPackShareServer.Entry{key=p.key,hash=p.sha256,bytes=p.bytes,path=CharacterPackService.EditorBundlePath(p)}));service.OverrideUrl=key=>{var item=CharacterPackService.Find(key);return "http://127.0.0.1:"+source.Port+"/packs/"+item.sha256+"?ticket="+source.Ticket;};service.DownloadGroup(false);yield return WaitDownload();Check(CharacterPackService.All.Where(p=>p.available).All(p=>CharacterPackService.Installed(p.key)),"Batch download installs every published optional pack");Check(CharacterPackService.ReviewLoadedBundles<=32,"Bulk download does not retain every role bundle in RAM");
            foreach(var role in CharacterRoster.All)if(CharacterRoster.Favorite(role.key))CharacterRoster.Star(role.key);
            var sorted=CharacterRoster.Ordered(false,true).ToArray();for(int i=0;i<9;i++)CharacterRoster.Star(sorted[i].key);
            lobby.PreviewDorm("yiji");yield return Shot("all-installed");lobby.ReviewOpenSort();yield return Hold(12);
            var first=lobby.ReviewSortRect(true,0);var ninth=lobby.ReviewSortRect(true,8);
            Check(Mathf.Approximately(first.x,ninth.x)&&Mathf.Approximately(ninth.y-first.y,184),"The ninth starred portrait wraps to the next row");
            Check(lobby.ReviewSortRect(false,0).y>=ninth.yMax,"Non-starred section follows all starred rows without overlap");yield return Shot("sort-all-start");
            lobby.ReviewSortScrollToEnd();yield return Hold(8);var last=lobby.ReviewSortRect(false,sorted.Length-10);
            Check(last.y>=80&&last.yMax<=864,"The final character is fully reachable in the sorting viewport");yield return Shot("sort-all-end");
            // Six partly visible rows can touch 48 roles in one frame. The soft
