            Check(CharacterPackService.ReviewLoadedBundles<=50,"Sorting retains at most the visible grid plus active roles, not the entire roster");
            var prior=sorted.Take(9).First(r=>!CharacterPackService.Protected(r.key)&&r.key!=CharacterRoster.Active.character&&r.key!=CharacterRoster.Dorm.key);
            Check(!AssetBundle.GetAllLoadedAssetBundles().Any(b=>b.name==CharacterPackService.Find(prior.key).file),"An unpinned portrait from the previous sorting page was released");lobby.PreviewHideCharacters();
            client.LobbyOpenSettings();settings.Tab=2;yield return Ui("resources-delete-all");yield return Shot("delete-all-confirmation");yield return Ui("delete-all-confirm");Check(CharacterPackService.All.All(p=>CharacterPackService.Installed(p.key)==p.builtin),"Delete all preserves only protected base characters");client.LobbyOpenSettings();settings.Tab=2;yield return Shot("settings-after-delete-all");yield return Ui("resources-custom");yield return Ui("resource-select-bamuwei");Check(CharacterResourceUi.Current.SelectedCount==1,"Custom selection chooses only the requested character");yield return Shot("settings-custom-selection");yield return Ui("resource-select-bamuwei");yield return Ui("resources-custom");
        }
        IEnumerator RoomCase(bool lan){
            CharacterRoster.Use("bamuwei",400701);lobby.PreviewHideCharacters();client.LobbyCreate(3,1,true,"friend");yield return Until(()=>client.LobbyActive&&client.State?.phase=="lobby"&&!client.Busy,"room create");string host=HostToken;yield return Raw(new RequestBody{op="join",name="资源提供者",pin=client.State.pin,character="weilai",skin=406901,resourceProtocol=1});string guest=rawReply.token;yield return Until(()=>!client.Busy,"room idle");yield return Raw(new RequestBody{op="addBot",token=host,version=rawReply.state.version});yield return Raw(new RequestBody{op="lobbyReady",token=guest,ready=true,version=rawReply.state.version});
            CharacterPackShareServer guestSource=null;if(lan){var record=CharacterPackService.Find("weilai");string file=CharacterPackService.EditorBundlePath(record);guestSource=new CharacterPackShareServer{Enabled=true,ReviewChunkDelayMs=2};guestSource.SetEntries(new[]{new CharacterPackShareServer.Entry{key=record.key,hash=record.sha256,bytes=record.bytes,path=file}});yield return Raw(new RequestBody{op="resourceOffer",token=guest,resourceShare=new ResourceShareRequest{port=guestSource.Port,ticket=guestSource.Ticket,hashes=new[]{record.sha256}}});}
            yield return Until(()=>client.State.players.Length==3&&!client.Busy,"all seats");client.LobbyCommand("start");yield return Until(()=>client.State.resourceSetup!=null&&!client.Busy,"frozen setup");var coordinator=client.GetComponent<ResourceRoomCoordinator>();yield return Shot(lan?"room-lan-choice":"room-missing-choice");coordinator.ReviewPress=lan?"room-resource-lan":"room-resource-fallback";yield return Hold(8);if(lan)yield return WaitDownload();yield return Until(()=>client.State.resourceSetup?.players?.FirstOrDefault()?.state==(lan?"ready":"fallback"),"host resource acknowledgement");Check(client.State.phase=="lobby","Room waits for the other human resource confirmation");yield return Shot(lan?"room-lan-ready":"room-fallback-ready");int revision=client.State.resourceSetup.revision;yield return Raw(new RequestBody{op="resourceAck",token=guest,setupRevision=revision,resourceStatus="ready"});yield return Until(()=>client.State.phase=="play","actual start after barrier");Check(client.State.players.Any(p=>p.character=="weilai"),"Local fallback never rewrites the other player's actual character");if(!lan)Check(CharacterRoster.Skin("weilai",406901).id==400101,"Missing peer illustration resolves to local 一姬");yield return Hold(45);yield return Shot(lan?"table-after-lan":"table-with-fallback");client.EndCurrentMatch();yield return Until(()=>!client.LobbyActive&&!client.Busy,"leave test match");guestSource?.Dispose();yield return Hold(5);
        }
        void Cleanup(){source?.Dispose();relay?.Dispose();Application.logMessageReceived-=Log;CharacterRoster.EndPreview();AudioListener.pause=false;}
    }
